contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint fund, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund) + (amount)); require(fund <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(fund > 0);
        require(amount > 0);
        require(amount < fund);
        require(address(this).balance >= fund);
        c.multiplicate{value: fund}(address(this)); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        bool reverted;
        c.multiplicate{value: amount}(address(0xdead)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;
        assert(!reverted && balAfter >= balBefore && balAfter - balBefore == amount);
    }
    receive() external payable {}
}

